export function prepareTemplate(template, values={}, publicReply=false) {
  if(!template)throw Error('Escolha um modelo para continuar.');
  for(const key of template.fields){const value=String(values[key]||'').trim();if(!value||value.length>500)throw Error('Preencha os detalhes do modelo com até 500 caracteres.');if(key==='link'){let url;try{url=new URL(value);}catch{throw Error('Informe um link completo começando com https://.');}if(url.protocol!=='https:'||url.username||url.password)throw Error('Use um link https:// sem usuário ou senha.');}}
  const text=template.text.replace(/\{(link|coupon|price|answer)\}/g,(_,key)=>String(values[key]||'').trim());
  if(text.length>1000)throw Error('A mensagem ficou muito longa. Reduza os detalhes do modelo.');
  const actions=[{type:template.trigger_type.startsWith('comment')?'private_reply':'message',text}];
  if(publicReply&&template.trigger_type.startsWith('comment'))actions.push({type:'public_reply',text:'Enviei as informações por mensagem privada. Confira seu Direct!'});
  return {name:template.name,trigger_type:template.trigger_type,scope:'all',configuration:{keywords:[...template.keywords],media_ids:[],once_per_contact:template.trigger_type.startsWith('comment'),actions}};
}
