export function previewConversation(graph,{reply='',timeout=false}={}){
  const nodes=new Map((graph?.nodes||[]).map(n=>[n.id,n])),trace=[];let id=graph?.start;const seen=new Set();
  while(id&&trace.length<30){if(seen.has(id)){trace.push({type:'error',text:'Há uma conexão circular neste caminho.'});break;}seen.add(id);const n=nodes.get(id);if(!n){trace.push({type:'error',text:'Há uma conexão sem destino.'});break;}
    if(n.type==='message'){trace.push({id:n.id,type:n.type,text:n.text});id=n.next;}
    else if(n.type==='wait_reply'){trace.push({id:n.id,type:n.type,text:timeout?'Sem resposta após '+Math.round(n.timeout_seconds/60)+' min.':reply?'Resposta de teste: '+reply:'A conversa aguardaria uma resposta.'});if(!reply&&!timeout)break;id=timeout?n.on_timeout:n.on_reply;}
    else if(n.type==='condition'){const normalize=x=>String(x).normalize('NFKC').toLocaleUpperCase(),match=n.operator==='equals'?normalize(reply).trim()===normalize(n.value).trim():normalize(reply).includes(normalize(n.value));trace.push({id:n.id,type:n.type,text:'Condição: '+(match?'Sim':'Não')});id=match?n.yes:n.no;}
    else if(n.type==='delay'){trace.push({id:n.id,type:n.type,text:'Aguardaria '+Math.round(n.seconds/60)+' min. antes de continuar.'});id=n.next;}
    else if(n.type==='end'){trace.push({id:n.id,type:n.type,text:'Fim deste caminho.'});break;}else break;
  }
  return trace;
}
export function publicationConflicts(candidate, flows){
  if(!candidate)return [];
  const config=flow=>{try{return typeof flow.configuration==='string'?JSON.parse(flow.configuration):flow.configuration||{};}catch{return {};}};
  const family=trigger=>trigger?.startsWith('comment')?'comment':trigger==='story_reply'?'story':'dm';
  const normalize=value=>String(value||'').normalize('NFKC').trim().toLocaleUpperCase();
  const incoming=config(candidate);
  return flows.filter(flow=>{
    if(flow.id===candidate.id||!flow.enabled||flow.account_id!==candidate.account_id||family(flow.trigger_type)!==family(candidate.trigger_type))return false;
    const existing=config(flow);
    if(flow.scope==='selected'&&candidate.scope==='selected'&&!(existing.media_ids||[]).some(id=>(incoming.media_ids||[]).includes(id)))return false;
    if(flow.trigger_type==='comment_any'||candidate.trigger_type==='comment_any'||candidate.trigger_type==='story_reply')return true;
    return (existing.keywords||[]).some(word=>(incoming.keywords||[]).some(other=>{const a=normalize(word),b=normalize(other);return a&&b&&(a.includes(b)||b.includes(a));}));
  });
}
