    async function persistGraph(){if(!form.reportValidity())throw Error('Confira os campos da conversa e do bloco selecionado.');if(scope.value==='selected'&&trigger.value.startsWith('comment')&&!mediaIds.value.trim())throw Error('Selecione pelo menos uma publicação para iniciar esta conversa.');const payload={workspace_id:state.workspace,account_id:account.value,name:name.value.trim(),trigger_type:trigger.value,scope:trigger.value.startsWith('comment')?scope.value:'all',configuration:{keywords:keywords.value.split(',').map(v=>v.trim()).filter(Boolean),media_ids:mediaIds.value.split(',').map(v=>v.trim()).filter(Boolean),once_per_contact:config.once_per_contact===true,graph,graph_layout:layout}};const result=await api('/api/flows'+(flow.id?'/'+encodeURIComponent(flow.id):''),{method:flow.id?'PATCH':'POST',body:JSON.stringify(payload)});flow.id=result.flow?.id||result.id||flow.id;if(!flow.id)throw Error('O servidor não confirmou o salvamento da conversa.');await refreshFlows();return flow.id;}
    const test=node('section',undefined,'graph-results');test.append(node('h3','Teste um caminho sem enviar mensagens'));const testInput=field(test,'Mensagem que inicia a conversa','text',(config.keywords||['INICIAR'])[0]||'Olá');const testReply=field(test,'Resposta da pessoa no teste','text','SIM');const timeoutLabel=node('label',undefined,'check'),timeout=node('input');timeout.type='checkbox';timeoutLabel.append(timeout,node('span','Simular que a pessoa não respondeu até o tempo limite'));test.append(timeoutLabel);const testMedia=field(test,'Publicação no teste (opcional)','text',(config.media_ids||[])[0]||'');const results=node('div');results.setAttribute('aria-live','polite');test.append(action('Salvar e testar caminho',async()=>{const id=await persistGraph(),result=await post('/api/flows/'+encodeURIComponent(id)+'/simulate',{text:testInput.value,media_id:testMedia.value||undefined,trigger_type:trigger.value});results.replaceChildren();if(!result.matched){results.append(node('p','Este evento não inicia a conversa. Confira a palavra-chave e a publicação escolhida.'));return;}let path=previewConversation(result.graph||graph,{reply:testReply.value,timeout:timeout.checked});if(trigger.value.startsWith('comment')&&timeout.checked){path=previewConversation(result.graph||graph);path.push({type:'end',text:'Sem resposta no Direct, encerra sem enviar outra mensagem privada.'});}results.append(node('p','Prévia lógica do caminho. Nenhuma mensagem foi enviada e nenhum tempo real foi aguardado. O servidor confere a janela da Meta antes de cada envio.'));const ordered=node('ol');for(const step of path){const item=node('li');item.append(node('strong',(labels[step.type]||'Revisar')+': '),node('span',step.text));ordered.append(item);}results.append(ordered);tell('Caminho de teste concluído.','success');},'secondary'),results);dialog.append(test);
